parameters.jsCode:
// WICHTIG: 'Recherche-Agent' (Tools Agent) gibt auf dem Erfolgspfad NUR seine
// eigene Antwort als $json zurueck; researchCandidateName/researchBatchId aus
// dem urspruenglichen Trigger-Item werden NICHT durchgereicht. Deshalb wird der
// Trigger-Kontext hier explizit erneut geholt (analog zu 'Fan-in-Kontext
// herstellen' in due-diligence-subworkflow.json), statt ihn aus $input.item.json
// zu lesen - sonst waeren researchRuntimeBatchId/-Candidate leer und der Fan-in
// im Parent wuerde diesen Kandidaten nie finden.
const trigger = $('Wenn von anderem Workflow aufgerufen').first().json;
const candidate = trigger.researchCandidateName;
const raw = $input.item.json;
const out = (raw.output && typeof raw.output === 'object') ? raw.output : raw;
const now = new Date().toISOString();

const news = Array.isArray(out.news)
  ? out.news.filter((entry) => typeof entry === 'string' && entry.trim().length > 0)
  : [];
const club = out.club || null;
const contract = out.contract || null;
const marketValue = out.marketValue || null;
const injuries = out.injuries || null;
const currentSituation = out.currentSituation || null;
const transferLikelihoodNotes = out.transferLikelihoodNotes || null;
const source = out.source || 'Websuche (Quelle nicht spezifiziert)';

// Maschinenlesbare Zusatzfelder fuer 'Empfehlung erzeugen'
// (empfehlung-erstellen-subworkflow.json): der Agent liefert 'contract'/
// 'marketValue' als Freitext, den die dortige Feasibility-Bewertung nur ueber
// ein enges DD.MM.YYYY-/Keyword-Muster auswerten kann. contractEndDate/
// marketValueMEUR sind deshalb kanonisch und werden dort bevorzugt genutzt,
// mit Freitext-Parsing weiterhin als Fallback.
const contractEndDateRaw = typeof out.contractEndDate === 'string' ? out.contractEndDate.trim() : null;
const contractEndDate = (contractEndDateRaw && /^\d{4}-\d{2}-\d{2}$/.test(contractEndDateRaw) && !Number.isNaN(Date.parse(contractEndDateRaw)))
  ? contractEndDateRaw
  : null;
const marketValueMEUR = (typeof out.marketValueMEUR === 'number' && Number.isFinite(out.marketValueMEUR))
  ? out.marketValueMEUR
  : null;

let confidence = typeof out.confidence === 'number' ? out.confidence : 0;
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.max(0, Math.min(1, confidence));

// Nur mit allen fachlichen Pflichtfeldern (siehe 'Recherche pruefen' in
// due-diligence-subworkflow.json) gilt der Zweig als nicht 'uncertain'.
const hasCoreFacts = Boolean(club) && Boolean(contract) && Boolean(marketValue) && Boolean(injuries) && news.length > 0;
const uncertain = !hasCoreFacts;

const researchResult = {
  candidate,
  club,
  contract,
  contractEndDate,
  marketValue,
  marketValueMEUR,
  injuries,
  currentSituation,
  transferLikelihoodNotes,
  news,
  source,
  timestamp: now,
  confidence: uncertain ? 0 : confidence,
  uncertain,
  uncertaintyReason: uncertain
    ? 'Websuche konnte nicht alle erforderlichen Angaben (Verein, Vertrag, Marktwert, Verletzungen, News) belastbar ermitteln.'
    : null
};

return [{
  json: {
    ...trigger,
    researchRuntimeBatchId: trigger.researchBatchId,
    researchRuntimeCandidate: candidate,
    researchRuntimeStatus: uncertain ? 'uncertain' : 'success',
    researchRuntimePayload: JSON.stringify(researchResult),
    researchRuntimeCompletedAt: now
  }
}];

// WICHTIG: der Fehlerausgang von 'Recherche-Agent' enthaelt nur { error,
// pairedItem } - researchCandidateName/researchBatchId aus dem urspruenglichen
// Trigger-Item fehlen hier ebenfalls (siehe Kommentar in
// 'Recherche-Ergebnis normalisieren'). Deshalb wird der Trigger-Kontext auch
// hier explizit erneut geholt statt aus $input.item.json gelesen.
const trigger = $('Wenn von anderem Workflow aufgerufen').first().json;
const candidate = trigger.researchCandidateName || 'unbekannter Kandidat';
const current = $input.item.json || {};
const reason = (current.error && (current.error.message || current.error)) || 'Recherche-Agent konnte kein Ergebnis liefern.';
const now = new Date().toISOString();

const researchResult = {
  candidate,
  club: null,
  contract: null,
  contractEndDate: null,
  marketValue: null,
  marketValueMEUR: null,
  injuries: null,
  currentSituation: null,
  transferLikelihoodNotes: null,
  news: [],
  source: 'Websuche fehlgeschlagen (keine Quelle verfuegbar)',
  timestamp: now,
  confidence: 0,
  uncertain: true,
  uncertaintyReason: String(reason)
};

return [{
  json: {
    ...trigger,
    researchRuntimeBatchId: trigger.researchBatchId,
    researchRuntimeCandidate: candidate,
    researchRuntimeStatus: 'agent_error',
    researchRuntimePayload: JSON.stringify(researchResult),
    researchRuntimeCompletedAt: now
  }
}];
